        // dp[k][sum] = number of ways to distribute 'sum' among (p-1) players
        // with each <= x and exactly k players equal to x
        val dp = Array(p) { LongArray(remaining + 1) }
        dp[0][0] = 1L

        for (sum in 0..remaining) {
            for (k in 0 until p - 1) {
                val cur = dp[k][sum]
                if (cur == 0L) continue
                // Next player score t from 0..min(x, remaining - sum)
                val maxT = minOf(x, remaining - sum)
                var t = 0
                while (t <= maxT) {
                    val nk = if (t == x) k + 1 else k
                    dp[nk][sum + t] = (dp[nk][sum + t] + cur) % MOD
                    t++
                }
            }
        }

        // For each k (number of opponents with score x), Hasan's winning probability:
        // 1 if k = 0 (strictly greater), 1/(k+1) otherwise
        for (k in 0 until p) {
            val ways = dp[k][remaining]
            if (ways == 0L) continue
            val prob = if (k == 0) 1L else modPow((k + 1).toLong(), MOD - 2)
            numerator = (numerator + ways * prob) % MOD
        }
    }

    if (totalStates == 0L) {
        println(0)
        return
    }

    val ans = numerator * modPow(totalStates, MOD - 2) % MOD
    println(ans)
}

import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

private const val MOD: Long = 998244353L

fun modAdd(a: Long, b: Long): Long {
    var res = a + b
    if (res >= MOD) res -= MOD
    return res
}

fun modSub(a: Long, b: Long): Long {
    var res = a - b
    if (res < 0) res += MOD
    return res
}

fun modMul(a: Long, b: Long): Long {
    return (a * b) % MOD
}

fun modPow(base: Long, exp: Long): Long {
    var b = base
    var e = exp
    var res = 1L
    while (e > 0) {
        if ((e and 1L) != 0L) res = modMul(res, b)
        b = modMul(b, b)
        e = e shr 1
    }
    return res
}

fun modInv(a: Long): Long = modPow(a, MOD - 2)

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(br.readLine())
    val p = st.nextToken().toInt()
    val s = st.nextToken().toInt()
    val r = st.nextToken().toInt()

    val maxN = s + p + 5
    val fact = LongArray(maxN)
    val invFact = LongArray(maxN)
    fact[0] = 1L
    for (i in 1 until maxN) fact[i] = modMul(fact[i - 1], i.toLong())
    invFact[maxN - 1] = modInv(fact[maxN - 1])
    for (i in maxN - 2 downTo 0) invFact[i] = modMul(invFact[i + 1], (i + 1).toLong())

    fun comb(n: Int, k: Int): Long {
        if (k < 0 || k > n) return 0L
        return modMul(fact[n], modMul(invFact[k], invFact[n - k]))
    }

    // total states: a1 >= r, others >= 0, sum = s
    // let x1 = a1 - r >= 0, sum x1 + a2 + ... + ap = s - r
    val totalStates = if (s - r < 0) 0L else comb(s - r + p - 1, p - 1)

    var winStates = 0L

    // iterate Hasan's score a1
    for (a1 in r..s) {
        val rem = s - a1
        if (rem < 0) continue

        // number of ways to distribute rem among p-1 players with each <= a1
        // using inclusion-exclusion on upper bound
        var waysAll = 0L
        var k = 0
        while (k <= p - 1 && k * (a1 + 1) <= rem) {
            val sign = if (k % 2 == 0) 1L else MOD - 1L
            val valComb = comb(p - 1, k)
            val valInner = comb(rem - k * (a1 + 1) + p - 2, p - 2)
            val term = modMul(sign, modMul(valComb, valInner))
            waysAll = modAdd(waysAll, term)
            k++
        }

        // count states where Hasan is unique max
        // subtract states where some other player ties with a1
        var tieStates = 0L
        if (a1 > 0 && p >= 2) {
            // choose t players among p-1 to tie with a1 (t >=1)
            for (t in 1..(p - 1)) {
                if (t * a1 > rem) break
                val rem2 = rem - t * a1
                // remaining p-1-t players have scores in [0, a1-1]
                // let bi in [0, a1-1]; transform ci = (a1-1) - bi >=0
                // sum ci = (p-1-t)*(a1-1) - rem2 >=0
                val sumCi = (p - 1 - t) * (a1 - 1) - rem2
                if (sumCi < 0) continue
                // number of nonnegative solutions for ci: C(sumCi + p-2-t, p-2-t)
                val cnt = comb(sumCi + p - 2 - t, p - 2 - t)
                val chooseT = comb(p - 1, t)
                val contrib = modMul(chooseT, cnt)
                tieStates = modAdd(tieStates, contrib)
            }
        }

        val uniqueMax = modSub(waysAll, tieStates)

        // states where Hasan is among top (including ties)
        val topStates = modAdd(uniqueMax, tieStates)

        // probability Hasan wins given this a1:
        // uniqueMax * 1 + sum over tie configurations (1 / (1 + #other top))
        // But we already aggregated tieStates without distinguishing t.
        // Need more detailed counting: recompute with t.

        var winGivenA1 = uniqueMax

        if (a1 > 0 && p >= 2) {
            for (t in 1..(p - 1)) {
                if (t * a1 > rem) break
                val rem2 = rem - t * a1
                val sumCi = (p - 1 - t) * (a1 - 1) - rem2
                if (sumCi < 0) continue
                val cnt = comb(sumCi + p - 2 - t, p - 2 - t)
                val chooseT = comb(p - 1, t)
                val statesThisT = modMul(chooseT, cnt)
                val invPlayers = modInv((t + 1).toLong())
                val contrib = modMul(statesThisT, invPlayers)
                winGivenA1 = modAdd(winGivenA1, contrib)
            }
        }

        winStates = modAdd(winStates, winGivenA1)
    }

    if (totalStates == 0L) {
        println(0)
        return
    }

    val ans = modMul(winStates, modInv(totalStates))
    println(ans)
